19:   @SneakyThrows
20:   @Override
21:   protected void convert(Scheduler source, SchedulerDTO target) {
22:     target.setName(source.getSchedulerName());
23:     target.setInstanceId(source.getSchedulerInstanceId());
24:     if(!source.isShutdown())
25:       target.setTriggerKeys(source.getTriggerKeys(GroupMatcher.anyTriggerGroup()));
26:     target.setStatus(buildTheSchedulerStatus(source));
27:     SchedulerMetaData metaData = source.getMetaData();
28:     target.setQuartzVersion(metaData.getVersion());
29:     target.setJobStoreClass(metaData.getJobStoreClass().getName());
30:     target.setJobStoreSupportsPersistence(metaData.isJobStoreSupportsPersistence());
31:     target.setClustered(metaData.isJobStoreClustered());
32:     target.setThreadPoolClass(metaData.getThreadPoolClass().getName());
33:     target.setThreadPoolSize(metaData.getThreadPoolSize());
34:     target.setNumberOfJobsExecuted(metaData.getNumberOfJobsExecuted());
35:     if (metaData.getRunningSince() != null)
36:       target.setRunningSince(DateTimeFormatter.ISO_OFFSET_DATE_TIME.format(metaData.getRunningSince().toInstant().atOffset(ZoneOffset.UTC)));
37:   }
