39:   private SchedulerStatus buildTheSchedulerStatus(Scheduler scheduler) throws SchedulerException {
40:     if (scheduler.isShutdown() || !scheduler.isStarted())
41:       return SchedulerStatus.STOPPED;
42:     else if (scheduler.isStarted() && scheduler.isInStandbyMode())
43:       return SchedulerStatus.PAUSED;
44:     return SchedulerStatus.RUNNING;
45:   }

